const state = sdk.getState();
console.log('Position:', state.player.worldX, state.player.worldZ);
console.log('Combat Level:', state.player.combatLevel);
console.log('HP:', state.player.hp, '/', state.player.maxHp);
console.log('Inventory:', state.inventory.items.map(i => i ? `${i.name} x${i.quantity}` : 'empty').filter(Boolean));
console.log('Nearby NPCs:', state.npcs.slice(0, 20).map(n => `${n.name} (${n.worldX}, ${n.worldZ}) lvl:${n.combatLevel} hp:${n.hp}/${n.maxHp}`));
console.log('Nearby Players:', state.players.slice(0, 10).map(p => `${p.name} (${p.worldX}, ${p.worldZ})`));

// Attack nearby rats
const rat = sdk.findNearbyNpc(/^rat$/i);
if (rat) {
  console.log('Found rat:', rat.name, 'at', rat.worldX, rat.worldZ, 'lvl:', rat.combatLevel);
  const result = await bot.attack(rat);
  console.log('Attack result:', result);
} else {
  console.log('No rat found nearby');
}

// Kill more rats
const rat = sdk.findNearbyNpc(/^rat$/i);
if (rat && rat.hp > 0) {
  console.log('Found rat:', rat.name, 'at', rat.worldX, rat.worldZ, 'lvl:', rat.combatLevel, 'hp:', rat.hp);
  const result = await bot.attack(rat);
  console.log('Attack result:', result);
} else {
  console.log('No live rat found nearby');
  // Check state for dead rat drops
  const state = sdk.getState();
  console.log('Ground items:', state.groundItems.map(g => `${g.name} x${g.quantity} at (${g.worldX}, ${g.worldZ})`));
}

// Dismiss level up dialog and attack imp
await bot.dismissBlockingUI();
const state = sdk.getState();
console.log('Dialog open:', state.dialog?.isOpen);
if (state.dialog?.isOpen) {
  await sdk.clickDialogByText(/continue/i);
}

